// Reads Your settings, checks them, and turns your website list into one item per site.
// A problem with the settings stops the run here, where n8n shows it in red.
const s = $('Your settings').first().json;

const phone = v => {
  const raw = String(v || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (raw.startsWith('+') && digits.length >= 8 && digits.length <= 15) return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return '';
};
// Reads a number setting. A blank falls back to the default, but 0 is kept, because 0 switches a check off.
const num = (v, d) => (v === '' || v === null || v === undefined || isNaN(Number(v))) ? d : Number(v);
const hhmm = (v, d) => /^([01]?\d|2[0-3]):[0-5]\d$/.test(String(v || '').trim()) ? String(v).trim() : d;

const business_number = phone(s.business_number);
const owner_cell = phone(s.owner_cell);
if (!business_number || !owner_cell) {
  throw new Error('Your settings: business_number and owner_cell must both be phone numbers, like +15551234567.');
}
if (['+15555550100', '+15555550199'].includes(business_number) || ['+15555550100', '+15555550199'].includes(owner_cell)) {
  throw new Error('Your settings: replace the example phone numbers with your Twilio number and your cell before you activate this.');
}
const timezone = String(s.timezone || 'America/New_York').trim();
if (!DateTime.now().setZone(timezone).isValid) {
  throw new Error('Your settings: "' + timezone + '" is not a time zone n8n knows. Use a name like America/New_York.');
}

const cfg = {
  business_name: String(s.business_name || 'your business').trim(),
  business_number,
  owner_cell,
  timezone,
  fails_before_alert: Math.max(1, num(s.fails_before_alert, 2)),
  remind_every_hours: Math.max(0, num(s.remind_every_hours, 4)),
  balance_floor: Math.max(0, num(s.balance_floor, 20)),
  block_window_minutes: Math.max(5, num(s.block_window_minutes, 60)),
  block_alert_count: Math.max(0, num(s.block_alert_count, 3)),
  quiet_start: hhmm(s.quiet_start, '21:00'),
  quiet_end: hhmm(s.quiet_end, '07:00'),
  routing_alerts_at_night: s.routing_alerts_at_night !== false && s.routing_alerts_at_night !== 'false',
  morning_check_in: s.morning_check_in !== false && s.morning_check_in !== 'false',
};

// One site per line: "https://example.com" or "https://example.com | text the page must contain".
const sites = String(s.websites || '')
  .split(/[\r\n]+/)
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('#'))
  .map(line => {
    const [first, ...rest] = line.split('|');
    let url = first.trim();
    if (!/^https?:\/\//i.test(url)) url = 'https://' + url;
    const label = url.replace(/^https?:\/\//i, '').replace(/\/$/, '');
    return { url, label, must_contain: rest.join('|').trim(), valid: /^https?:\/\/[a-z0-9-]+(\.[a-z0-9-]+)+(:\d+)?(\/\S*)?$/i.test(url) };
  });

if (!sites.length) return [{ json: { watching: false, cfg } }];
return sites.map(site => ({ json: { watching: true, ...site, cfg } }));

// Turns each website's answer into up or down, with the reason in plain words.
const plans = $('Plan the checks').all().map(i => i.json);
if (!plans[0].watching) return [{ json: { sites: [] } }];
const results = $input.all();

const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e;
  return [e.message, e.description, e.code, e.cause && (e.cause.code || e.cause.message)].filter(Boolean).join(' ');
};
const plain = e => {
  const t = errText(e);
  if (/ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(t)) return 'the address does not resolve, which is a domain or DNS problem';
  if (/CERT|certificate|SSL|TLS|self.signed/i.test(t)) return 'its security certificate failed, expired or not valid';
  if (/timeout|timed out|ETIMEDOUT|ECONNABORTED/i.test(t)) return 'no answer within 15 seconds';
  if (/ECONNREFUSED/i.test(t)) return 'the server refused the connection';
  if (/ECONNRESET|socket hang up/i.test(t)) return 'the connection dropped';
  const code = t.match(/status code (\d{3})/i);
  if (code) return 'the server answered ' + code[1];
  return 'it could not be reached (' + (t.slice(0, 80) || 'no reason given') + ')';
};

const sites = plans.map((p, i) => {
  const base = { url: p.url, label: p.label };
  if (!p.valid) return { ...base, ok: false, reason: 'this is not a web address I can check' };
  const r = (results[i] || {}).json || {};
  if (r.error) return { ...base, ok: false, reason: plain(r.error) };
  const code = Number(r.statusCode);
  if (!code) return { ...base, ok: false, reason: 'no answer' };
  if (code >= 400) {
    const kind = code === 404 ? ', page not found' : code >= 500 ? ', a server error' : '';
    return { ...base, ok: false, reason: 'the server answered ' + code + kind };
  }
  if (p.must_contain) {
    const raw = r.body !== undefined ? r.body : r.data;
    const body = typeof raw === 'string' ? raw : JSON.stringify(raw || '');
    if (!body.toLowerCase().includes(p.must_contain.toLowerCase())) {
      return { ...base, ok: false, reason: 'the page loads but "' + p.must_contain + '" is missing from it' };
    }
  }
  return { ...base, ok: true, reason: '' };
});

return [{ json: { sites } }];

// Compares this check with what the watchdog remembers and writes the text you get, if any.
// Its memory is n8n workflow static data. n8n keeps it between runs of an ACTIVE workflow;
// runs you start by hand in the editor do not save it, so each of those looks like a first run.
const cfg = $('Plan the checks').first().json.cfg;
const sites = $('Judge the websites').first().json.sites || [];
const balance = $('Your Twilio balance').first().json;
const routeRes = $('How your number is routed').first().json;
const logRes = $('Texts your number sent').first().json;

const st = $getWorkflowStaticData('global');
const now = DateTime.now().setZone(cfg.timezone);
const nowIso = now.toISO();
const at = iso => DateTime.fromISO(iso).setZone(cfg.timezone);
const hoursSince = iso => (iso ? now.diff(at(iso), 'hours').hours : Infinity);
const clock = dt => dt.toFormat('h:mm a');
const lasted = iso => {
  const m = Math.max(1, Math.round(now.diff(at(iso), 'minutes').minutes));
  if (m < 60) return m + ' min';
  const h = Math.floor(m / 60), r = m % 60;
  return r ? h + ' h ' + r + ' min' : h + ' h';
};
const money = v => (balance.currency && balance.currency !== 'USD' ? balance.currency + ' ' : '$') + Number(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

// Quiet hours. When start and end are the same there are none.
const toMin = t => { const [h, m] = String(t).split(':').map(Number); return h * 60 + (m || 0); };
const qs = toMin(cfg.quiet_start), qe = toMin(cfg.quiet_end), nowMin = now.hour * 60 + now.minute;
const quiet = qs === qe ? false : qs < qe ? (nowMin >= qs && nowMin < qe) : (nowMin >= qs || nowMin < qe);

const first = !st.started;
const today = now.toISODate();
// The first check at or after the end of quiet hours sends the morning check-in.
const morningDue = !first && !quiet && nowMin >= qe && st.morning !== today;

const out = [];
st.night = st.night || [];
// Everything goes through here. In quiet hours anything that is not urgent is kept for the morning.
// Reminders are skipped in quiet hours and on the morning check-in, which already says what is still wrong.
const say = (text, { urgent = false, reminder = false } = {}) => {
  if (reminder && (quiet || morningDue)) return;
  if (quiet && !urgent) { st.night.push(clock(now) + ' ' + text); return; }
  out.push(text);
};
const remindNow = () => !quiet;

// 1. Websites
st.sites = st.sites || {};
for (const s of sites) {
  const mem = st.sites[s.url] || { fails: 0 };
  if (s.ok) {
    if (mem.alerted) say(s.label + ' is back up after ' + lasted(mem.down_since) + '.');
    st.sites[s.url] = { fails: 0 };
    continue;
  }
  mem.fails = (mem.fails || 0) + 1;
  mem.down_since = mem.down_since || nowIso;
  mem.reason = s.reason;
  if (!mem.alerted && mem.fails >= cfg.fails_before_alert) {
    say(s.label + ' is down: ' + s.reason + '. First failed check at ' + clock(at(mem.down_since)) + '. I will text you when it is back.');
    mem.alerted = true;
    mem.last_alert = nowIso;
  } else if (mem.alerted && cfg.remind_every_hours > 0 && hoursSince(mem.last_alert) >= cfg.remind_every_hours) {
    say(s.label + ' is still down, ' + lasted(mem.down_since) + ' so far: ' + s.reason + '.', { reminder: true });
    if (remindNow()) mem.last_alert = nowIso;
  }
  st.sites[s.url] = mem;
}
// Forget sites you removed from the list.
for (const url of Object.keys(st.sites)) if (!sites.some(s => s.url === url)) delete st.sites[url];

// 2. Twilio balance. At $0 Twilio stops your texts and calls, and these alerts with them.
const bal = Number(balance.balance);
if (Number.isFinite(bal) && cfg.balance_floor > 0) {
  if (bal < cfg.balance_floor) {
    if (!st.balance_low) {
      say('Your Twilio balance is ' + money(bal) + ', under your ' + money(cfg.balance_floor) + ' floor. At $0 your texts and calls stop, and so do these alerts.');
      st.balance_low = true;
      st.balance_alert = nowIso;
    } else if (hoursSince(st.balance_alert) >= 24) {
      say('Your Twilio balance is still low: ' + money(bal) + '.', { reminder: true });
      if (remindNow()) st.balance_alert = nowIso;
    }
  } else if (st.balance_low) {
    say('Your Twilio balance is back up to ' + money(bal) + '.');
    st.balance_low = false;
  }
}

// 3. Where your number sends calls and texts. SIDs are shortened and query strings dropped.
const mask = v => String(v).replace(/\b(AC|AP|FW|TK|PN|MG)[0-9a-f]{32}\b/gi, (m, p) => p + '...' + m.slice(-4));
const where = (url, app, trunk) =>
  trunk ? 'SIP trunk ' + mask(trunk)
  : app ? 'TwiML app ' + mask(app)
  : url ? mask(String(url).replace(/^https?:\/\//i, '').split('?')[0]).slice(0, 80)
  : 'nowhere, no handler is set';
// If Twilio could not be asked, this check is skipped rather than guessed.
const routeKnown = !routeRes.error && Array.isArray(routeRes.incoming_phone_numbers);
const num = routeKnown ? routeRes.incoming_phone_numbers[0] : null;
let route = null;
if (!routeKnown) {
  // nothing to compare this time
} else if (!num) {
  if (!st.number_missing) {
    say(cfg.business_number + ' is not on your Twilio account any more. Calls and texts to it are not reaching you. Check the Twilio console now.', { urgent: true });
    st.number_missing = true;
  }
} else {
  if (st.number_missing) {
    say(cfg.business_number + ' is back on your Twilio account.', { urgent: true });
    st.number_missing = false;
  }
  route = {
    calls: where(num.voice_url, num.voice_application_sid, num.trunk_sid),
    texts: where(num.sms_url, num.sms_application_sid),
  };
  if (st.route) {
    for (const k of ['calls', 'texts']) {
      if (st.route[k] !== route[k]) {
        say((k === 'calls' ? 'Calls' : 'Texts') + ' to ' + cfg.business_number + ' used to go to ' + st.route[k] + '. They now go to ' + route[k] + '. If you did not change this, check Twilio now.', { urgent: cfg.routing_alerts_at_night });
      }
    }
  }
  st.route = route;
}

// 4. Carrier blocking. Only these errors mean a carrier stopped the text; a wrong or landline
// number fails on its own and is not a sign of trouble with your line.
const BLOCK = {
  30004: 'message blocked',
  30007: 'carrier filtering',
  30032: 'toll-free number not verified',
  30034: 'number not registered for A2P 10DLC',
};
const logKnown = !logRes.error && Array.isArray(logRes.messages);
const windowStart = now.minus({ minutes: cfg.block_window_minutes });
const recent = (logKnown ? logRes.messages : []).filter(m =>
  String(m.direction || '').startsWith('outbound') &&
  m.to !== cfg.owner_cell &&
  DateTime.fromRFC2822(String(m.date_created || '')).isValid &&
  DateTime.fromRFC2822(m.date_created) >= windowStart);
const blocked = recent.filter(m => ['failed', 'undelivered'].includes(m.status) && BLOCK[m.error_code]);
if (cfg.block_alert_count > 0 && blocked.length >= cfg.block_alert_count && hoursSince(st.block_alert) * 60 >= cfg.block_window_minutes) {
  const counts = {};
  for (const m of blocked) counts[m.error_code] = (counts[m.error_code] || 0) + 1;
  const why = Object.entries(counts).map(([c, n]) => c + ' ' + BLOCK[c] + ' (' + n + ')').join(', ');
  say(blocked.length + ' of the ' + recent.length + ' texts your number sent in the last ' + cfg.block_window_minutes + ' min were blocked by carriers: ' + why + '. Those customers did not get them.');
  st.block_alert = nowIso;
}

// Status line for the first run and the morning check-in.
const down = sites.filter(s => !s.ok);
const status = [
  !sites.length ? 'no websites watched'
    : !down.length ? (sites.length === 1 ? 'website up' : 'all ' + sites.length + ' websites up')
    : down.map(s => s.label + ' down (' + s.reason + ')').join(', '),
  Number.isFinite(bal) ? 'Twilio balance ' + money(bal) + (cfg.balance_floor > 0 && bal < cfg.balance_floor ? ', under your ' + money(cfg.balance_floor) + ' floor' : '') : 'Twilio balance unknown',
  route ? 'calls go to ' + route.calls : routeKnown ? cfg.business_number + ' missing from Twilio' : 'routing unknown',
  logKnown ? blocked.length + ' of ' + recent.length + ' texts blocked in the last ' + cfg.block_window_minutes + ' min' : 'text log unknown',
].join(', ') + '.';

if (first) {
  const watching = (sites.length ? sites.map(s => s.label).join(', ') + ', ' : '') + cfg.business_number + ', your Twilio balance and carrier blocking' + (sites.length ? '' : ' (no websites listed)');
  out.unshift('now on for ' + cfg.business_name + '. Watching ' + watching + '. Right now: ' + status +
    (cfg.morning_check_in ? ' You get a short check-in each morning at ' + clock(DateTime.fromObject({ hour: Math.floor(qe / 60), minute: qe % 60 })) + '. Otherwise' : ' From here') + ' you only hear from me when something breaks or recovers.');
  st.started = nowIso;
  st.morning = today;
} else if (morningDue) {
  // What happened overnight, and where things stand.
  st.morning = today;
  const lines = [];
  if (st.night.length) lines.push('Overnight: ' + st.night.join(' '));
  if (st.night.length || cfg.morning_check_in) lines.push('Right now: ' + status);
  if (lines.length) out.unshift('Morning check-in. ' + lines.join('\n'));
  st.night = [];
}

// Anything that failed to send last time goes again, for up to 24 hours.
st.unsent = (st.unsent || []).filter(u => hoursSince(u.at) < 24);
const lines = [...st.unsent.map(u => u.text), ...out];
st.unsent = [...st.unsent, ...out.map(text => ({ text, at: nowIso }))];
let body = '';
if (lines.length === 1) body = 'Watchdog: ' + lines[0];
if (lines.length > 1) body = 'Watchdog:\n' + lines.map(l => '- ' + l).join('\n');
if (body.length > 1500) body = body.slice(0, 1480) + '... (cut short)';

return [{ json: {
  send: body.length > 0,
  body,
  from: cfg.business_number,
  to: cfg.owner_cell,
  quiet,
  first_run: first,
  status,
  held_for_morning: st.night.length,
} }];

// The text went out, so nothing is waiting to be retried.
$getWorkflowStaticData('global').unsent = [];
return [{ json: { delivered: true, sid: $json.sid } }];
